## Problem 5 — the diff

Edit `ex5/solution.ts`. Implement:

```ts
export interface Totals { name: string; count: number; selfSize: number; }
export interface Growth {
  name: string;
  countDelta: number;
  bytesDelta: number;
  ratio: number;         // after.selfSize / before.selfSize, Infinity when before was 0
}

export function diffSnapshots(
  before: readonly Totals[],
  after: readonly Totals[],
  options?: { minBytes?: number; minRatio?: number },
): Growth[]
```

Report constructors that grew, filtered by a noise floor: keep only entries
whose `bytesDelta` is at least `minBytes` (default 1_048_576) **and** whose
`ratio` is at least `minRatio` (default 1.05). Constructors present only in
`after` count as growth from zero. Sort by `bytesDelta` descending, tie-broken
by name.

```ts
diffSnapshots(
  [{ name: "Session", count: 10, selfSize: 1000 }],
  [{ name: "Session", count: 20_000, selfSize: 4_000_000 }],
  { minBytes: 1000, minRatio: 1.5 },
);
// [{ name: "Session", countDelta: 19_990, bytesDelta: 3_999_000, ratio: 4000 }]
```

```
uv run dojo test node v3nc04_memory_leaks ex5
```

references.solution.ts:
// v3nc04_memory_leaks / ex5 - reference solution (author only, used by `dojo verify`).

export interface Totals {
  name: string;
  count: number;
  selfSize: number;
}

export interface Growth {
  name: string;
  countDelta: number;
  bytesDelta: number;
  ratio: number;
}

// Note for callers: diff the SECOND and THIRD snapshots of a run, not the
// first and second. The first comparison is polluted by lazy initialisation,
// JIT warm-up and one-time caches, all of which look exactly like a leak.
export function diffSnapshots(
  before: readonly Totals[],
  after: readonly Totals[],
  options: { minBytes?: number; minRatio?: number } = {},
): Growth[] {
  const minBytes = options.minBytes ?? 1_048_576;
  const minRatio = options.minRatio ?? 1.05;
  const baseline = new Map(before.map((entry) => [entry.name, entry]));

  const growth: Growth[] = [];
  for (const entry of after) {
    const was = baseline.get(entry.name);
    const bytesDelta = entry.selfSize - (was?.selfSize ?? 0);
    // Infinity compares correctly against any threshold, so growth from zero
    // needs no special case in the filter.
    const ratio = was && was.selfSize > 0 ? entry.selfSize / was.selfSize : Infinity;

    // Absolute AND relative: the floor rejects a 40-byte object that grew
    // 100x, the ratio rejects a 200 MB cache that grew by 2 MB.
    if (bytesDelta < minBytes || ratio < minRatio) continue;

    growth.push({
      name: entry.name,
      countDelta: entry.count - (was?.count ?? 0),
      bytesDelta,
      ratio,
    });
  }

  return growth.sort((a, b) => b.bytesDelta - a.bytesDelta || a.name.localeCompare(b.name));
}

