## Challenge — a leak detector

Edit `challenge/solution.ts`. Combine the sector into one tool:

```ts
export interface Suspect {
  name: string;
  bytesDelta: number;
  countDelta: number;
  ratio: number;
  path?: string[];        // retainer path for the largest instance, if findable
  verdict: "leak" | "suspicious" | "noise";
}

export interface DetectorInput {
  before: { totals: Array<{ name: string; count: number; selfSize: number }> };
  after: {
    totals: Array<{ name: string; count: number; selfSize: number }>;
    graph: {
      nodes: Array<{ index: number; id: number; name: string; selfSize: number; edgeCount: number; firstEdge: number }>;
      edges: Array<{ toNode: number; name: string }>;
    };
  };
}

export function findSuspects(
  input: DetectorInput,
  options?: { minBytes?: number; minRatio?: number; leakRatio?: number },
): Suspect[]
```

For every constructor that grew past the noise floor (ex5's rule), find the
**largest instance by `selfSize`** with that name in the `after` graph, and
