// v3nc04_memory_leaks / challenge - reference solution (author only, used by `dojo verify`).

export interface Suspect {
  name: string;
  bytesDelta: number;
  countDelta: number;
  ratio: number;
  path?: string[];
  verdict: "leak" | "suspicious" | "noise";
}

interface GraphNode {
  index: number;
  id: number;
  name: string;
  selfSize: number;
  edgeCount: number;
  firstEdge: number;
}

export interface DetectorInput {
  before: { totals: Array<{ name: string; count: number; selfSize: number }> };
  after: {
    totals: Array<{ name: string; count: number; selfSize: number }>;
    graph: { nodes: GraphNode[]; edges: Array<{ toNode: number; name: string }> };
  };
}

// One BFS from the roots, reused for every suspect: every path we need starts
// at node 0, so re-running the search per suspect is pure waste.
function buildParents(graph: DetectorInput["after"]["graph"]): Map<number, { from: number; edge: string }> {
  const parent = new Map<number, { from: number; edge: string }>();
  const seen = new Set<number>([0]);
  const queue = [0];
  let head = 0;
  while (head < queue.length) {
    const current = queue[head++];
    const node = graph.nodes[current];
    if (!node) continue;
    for (let e = node.firstEdge; e < node.firstEdge + node.edgeCount; e++) {
      const edge = graph.edges[e];
      if (!edge || seen.has(edge.toNode)) continue;
      seen.add(edge.toNode);
      parent.set(edge.toNode, { from: current, edge: edge.name });
      queue.push(edge.toNode);
    }
  }
  return parent;
}

function pathTo(
  graph: DetectorInput["after"]["graph"],
  parent: Map<number, { from: number; edge: string }>,
  target: number,
): string[] | undefined {
  if (target === 0) return [graph.nodes[0].name];
  const path: string[] = [];
  let at = target;
  while (at !== 0) {
    const step = parent.get(at);
    if (!step) return undefined;
    path.push(graph.nodes[at].name, step.edge);
    at = step.from;
  }
  path.push(graph.nodes[0].name);
  return path.reverse();
}

export function findSuspects(
  input: DetectorInput,
  options: { minBytes?: number; minRatio?: number; leakRatio?: number } = {},
): Suspect[] {
  const minBytes = options.minBytes ?? 1_048_576;
  const minRatio = options.minRatio ?? 1.05;
  const leakRatio = options.leakRatio ?? 2;

  const baseline = new Map(input.before.totals.map((entry) => [entry.name, entry]));
  const parent = buildParents(input.after.graph);

  const suspects: Suspect[] = [];
  for (const entry of input.after.totals) {
    const was = baseline.get(entry.name);
    const bytesDelta = entry.selfSize - (was?.selfSize ?? 0);
    const ratio = was && was.selfSize > 0 ? entry.selfSize / was.selfSize : Infinity;
    if (bytesDelta < minBytes || ratio < minRatio) continue;

    const countDelta = entry.count - (was?.count ?? 0);

    // A heuristic, not a truth: the largest instance may be retained
    // differently from the other twelve thousand.
    let biggest: GraphNode | undefined;
    for (const node of input.after.graph.nodes) {
      if (node.name !== entry.name) continue;
      if (!biggest || node.selfSize > biggest.selfSize) biggest = node;
    }

    suspects.push({
      name: entry.name,
      bytesDelta,
      countDelta,
      ratio,
      path: biggest ? pathTo(input.after.graph, parent, biggest.index) : undefined,
      // "suspicious" rather than "leak" is how the uncertainty gets encoded
      // instead of hidden: self size understates containers, and one path
      // explains one instance.
      verdict: ratio >= leakRatio && countDelta > 0 ? "leak" : "suspicious",
    });
  }

  return suspects.sort((a, b) => b.bytesDelta - a.bytesDelta || a.name.localeCompare(b.name));
}

